{
  "summary": "Gather current Acme Cloud Services contract terms, renewal/pricing policy, SLA performance history, and any credits owed, then draft a reply addressing the proposed 12% increase and 12-month renewal.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (end date, pricing, renewal clauses, notice periods), read internal vendor renewal/pricing policy documents (e.g., caps on annual increases), read SLA terms and performance/incident logs for the contract period, run the SLA credit calculator to determine any credits owed to us, and if the contract or invoices are denominated in USD or another foreign currency, use the currency converter to express amounts in our reporting currency.",
      "why": "All facts needed for the renewal response—contract terms, pricing policy limits, SLA performance, and any credits owed—must be retrieved before drafting a reply."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the vendor email response to Acme Cloud Services addressing the proposed 12-month renewal and 12% price increase, referencing our internal pricing policy limits, citing SLA performance and any credits owed as leverage or offsets, and proposing final terms for human review and approval.",
      "why": "The executor synthesizes the retrieved facts into a complete, ready-to-review reply to the vendor."
    }
  ],
